import {existsSync,readFileSync} from 'node:fs';import {fileURLToPath} from 'node:url';import {registerHooks,stripTypeScriptTypes} from 'node:module';import {DatabaseSync} from 'node:sqlite';
registerHooks({resolve(s,c,n){if(s.startsWith('.')&&s.endsWith('.js')&&c.parentURL){const u=new URL(s.slice(0,-3)+'.ts',c.parentURL);if(existsSync(fileURLToPath(u)))return n(u.href,c);}return n(s,c);}});
const {digest,hashJson}=await import('../../packages/contracts/src/canonical.ts');const {requireThat}=await import('../../packages/contracts/src/errors.ts');
const source=readFileSync('services/task-board/src/runtime/store.ts','utf8'),schema=source.match(/\.exec\(`(PRAGMA journal_mode=WAL;[\s\S]*?)`\);/)[1];
const methods=source.slice(source.indexOf('  localKey('),source.indexOf('  close(): void'));
const Store=new Function('digest','hashJson','requireThat',stripTypeScriptTypes('class Store{local;constructor(db){this.local=db;}\n'+methods+'\n}')+'\nreturn Store;')(digest,hashJson,requireThat);
const rows=[],add=(name,pin,extra={})=>rows.push({name,input:{pin,...extra}});
add('missing',{objectId:'missing',revision:1});add('blob',{objectId:'blob',revision:1});
for(const revision of [0,2,1.5])add('blob revision '+revision,{objectId:'blob',revision});
for(const revision of [1,2,3,1.5])add('document revision '+revision,{objectId:'document',revision});
add('null parent',{objectId:'orphan',revision:1});add('blob takes identity precedence',{objectId:'collision',revision:2});
add('noncanonical raw JSON bytes',{objectId:'raw',revision:1});add('surrogate content',{objectId:'surrogate',revision:1});
for(const row of rows){const db=new DatabaseSync(':memory:');db.exec(schema);
 for(const [id,key,parent,bytes]of [['blob','task-board/native-evidence-chunk','owner','00ff8081'],['collision','task-board/native-read-evidence-chunk',null,'616263']])db.prepare('INSERT INTO blobs VALUES(?,?,?,?,?)').run(id,key,'part',parent,Buffer.from(bytes,'hex'));
 const documents=[['document','task-board/native-evidence','owner',2],['orphan','task-board/native-plan',null,1],['collision','task-board/native-read-evidence','owner',2],['raw','task-board/native-evidence','owner',1],['surrogate','task-board/native-evidence','owner',1]];
 const revisions=[['document',1,'{"value":"old"}'],['document',2,'{"value":"new"}'],['orphan',1,'null'],['collision',2,'{}'],['raw',1,' { "b": 2, "a": 1, "a": 3 } '],['surrogate',1,'{"value":"\\ud800"}']];
 for(const[id,key,parent,current]of documents)db.prepare('INSERT INTO documents VALUES(?,?,?,?,?,?,?)').run(id,key,id,parent,current,'time','time');
 for(const[id,revision,value]of revisions)db.prepare('INSERT INTO revisions VALUES(?,?,?,?)').run(id,revision,value,'time');
 row.documents=documents;row.revisions=revisions;row.blobs=[['blob','task-board/native-evidence-chunk','owner','00ff8081'],['collision','task-board/native-read-evidence-chunk',null,'616263']];
 try{const artifact=new Store(db).localArtifact(row.input.pin);row.expected=artifact?{...artifact,bytes:artifact.bytes.toString('hex')}:null;}catch(e){row.expected={error:{code:e.code,message:e.message}};}db.close();
}
process.stdout.write(JSON.stringify(rows));
